#include <vector>
#include <unordered_map>
#include <set>

using namespace std;

class Solution {
public:
    vector<int> avoidFlood(vector<int>& rains) {
        int n = rains.size();
        vector<int> res(n, 1);
        unordered_map<int, int> full;
        set<int> dryDays;

        for (int i = 0; i < n; ++i) {
            if (rains[i] == 0) {
                dryDays.insert(i);
                res[i] = 1; // default dry action
            } else {
                int lake = rains[i];
                if (full.count(lake)) {
                    auto it = dryDays.lower_bound(full[lake]);
                    if (it == dryDays.end()) return {};
                    res[*it] = lake;
                    dryDays.erase(it);
                }
                full[lake] = i;
                res[i] = -1;
            }
        }
        return res;
    }
};
